import{C as e,U as t,_ as n,h as r,i,m as a,n as o,t as s,v as c}from"./theme-DsjXXSTJ.js";import{n as l,t as u}from"./index-CrIxgge7.js";var d={class:`lise-layout`},f=o(c({__name:`DatenschutzView`,setup(o){return i(e=>({v40e2a900:t(s).dimensions.containerMaxWidth,v55fc08c0:t(s).spacing.md,v1866a7a4:t(s).colors.neutral[50],v104faeb5:t(s).spacing[`2xl`],f4711142:t(s).colors.neutral[200],v772acacd:t(s).typography.fontFamily.sans,v7991a52a:t(s).typography.fontSize[`3xl`],v2e83aa2b:t(s).typography.fontWeight.bold,f46ab410:t(s).colors.neutral[900],v55fc05f8:t(s).spacing.xs,c998bae4:t(s).typography.fontSize.base,f46c858c:t(s).colors.neutral[700],d621bc30:t(s).dimensions.borderRadius.lg,v55fc0606:t(s).spacing.xl,v1e4375f1:t(s).typography.fontSize.xl,v6a1bcf99:t(s).typography.fontWeight.semibold,v55fc073a:t(s).spacing.sm,v1e437478:t(s).typography.fontSize.lg,f46b9cce:t(s).colors.neutral[800],v55fc08f8:t(s).spacing.lg,d621bbf8:t(s).dimensions.borderRadius.md,v56fdd121:t(s).colors.primary[500],v56fe4580:t(s).colors.primary[600]})),(t,i)=>(e(),a(`div`,d,[n(l),i[0]||=r(`<main class="lise-main" data-v-e5407460><section class="lise-datenschutz-hero" data-v-e5407460><div class="lise-container" data-v-e5407460><h1 class="lise-datenschutz-hero__title" data-v-e5407460>Datenschutzerklärung</h1><p class="lise-datenschutz-hero__subtitle" data-v-e5407460> Informationen zur Verarbeitung Ihrer personenbezogenen Daten gemäß DSGVO </p></div></section><section class="lise-datenschutz-content" data-v-e5407460><div class="lise-container" data-v-e5407460><div class="lise-datenschutz-card" data-v-e5407460><article class="lise-ds-block" data-v-e5407460><h2 data-v-e5407460>1. Datenschutz auf einen Blick</h2><h3 data-v-e5407460>Allgemeine Hinweise</h3><p data-v-e5407460> Die folgenden Hinweise geben einen einfachen Überblick darüber, was mit Ihren personenbezogenen Daten passiert, wenn Sie unsere Website besuchen. Personenbezogene Daten sind alle Daten, mit denen Sie persönlich identifiziert werden können. </p></article><article class="lise-ds-block" data-v-e5407460><h2 data-v-e5407460>2. Verantwortliche Stelle</h2><p data-v-e5407460>Die verantwortliche Stelle für die Datenverarbeitung auf dieser Website ist:</p><div class="lise-address-box" data-v-e5407460><strong data-v-e5407460>STN ENTERPRISES GmbH</strong><br data-v-e5407460> Märkischer Ring 92<br data-v-e5407460> 58097 Hagen<br data-v-e5407460> Deutschland<br data-v-e5407460><br data-v-e5407460><strong data-v-e5407460>Telefon:</strong> 02331 - 4889720<br data-v-e5407460><strong data-v-e5407460>E-Mail:</strong> <a href="mailto:info@stnconsulting.de" class="lise-link" data-v-e5407460>info@stnconsulting.de</a></div></article><article class="lise-ds-block" data-v-e5407460><h2 data-v-e5407460>3. Datenerfassung auf unserer Website</h2><h3 data-v-e5407460>Server-Log-Dateien</h3><p data-v-e5407460> Der Provider der Seiten erhebt und speichert automatisch Informationen in sogenannten Server-Log-Dateien, die Ihr Browser automatisch an uns übermittelt. Dies sind: </p><ul data-v-e5407460><li data-v-e5407460>Browsertyp und Browserversion</li><li data-v-e5407460>Verwendetes Betriebssystem</li><li data-v-e5407460>Referrer URL</li><li data-v-e5407460>Hostname des zugreifenden Rechners</li><li data-v-e5407460>Uhrzeit der Serveranfrage</li><li data-v-e5407460>IP-Adresse</li></ul><p data-v-e5407460> Eine Zusammenführung dieser Daten mit anderen Datenquellen wird nicht vorgenommen. Die Erfassung dieser Daten erfolgt auf Grundlage von Art. 6 Abs. 1 lit. f DSGVO. </p><h3 data-v-e5407460>Kontaktformular</h3><p data-v-e5407460> Wenn Sie uns per Kontaktformular Anfragen zukommen lassen, werden Ihre Angaben aus dem Anfrageformular inklusive der von Ihnen dort angegebenen Kontaktdaten (Anrede, Name, E-Mail, Telefonnummer, Unternehmen, Grund der Anfrage und Nachricht) zwecks Bearbeitung der Anfrage und für den Fall von Anschlussfragen bei uns gespeichert. </p><p data-v-e5407460> Die Verarbeitung dieser Daten erfolgt auf Grundlage von Art. 6 Abs. 1 lit. b DSGVO, sofern Ihre Anfrage mit der Erfüllung eines Vertrags zusammenhängt oder zur Durchführung vorvertraglicher Maßnahmen erforderlich ist. In allen übrigen Fällen beruht die Verarbeitung auf unserem berechtigten Interesse an der effektiven Bearbeitung der an uns gerichteten Anfragen (Art. 6 Abs. 1 lit. f DSGVO) oder auf Ihrer Einwilligung (Art. 6 Abs. 1 lit. a DSGVO). </p></article><article class="lise-ds-block" data-v-e5407460><h2 data-v-e5407460>4. Ihre Rechte als betroffene Person</h2><p data-v-e5407460> Sie haben im Rahmen der geltenden gesetzlichen Bestimmungen jederzeit das Recht auf: </p><ul data-v-e5407460><li data-v-e5407460><strong data-v-e5407460>Auskunft (Art. 15 DSGVO):</strong> Recht auf Auskunft über Ihre von uns verarbeiteten personenbezogenen Daten.</li><li data-v-e5407460><strong data-v-e5407460>Berichtigung (Art. 16 DSGVO):</strong> Recht auf Unverzügliche Berichtigung unrichtiger oder Vervollständigung Ihrer Daten.</li><li data-v-e5407460><strong data-v-e5407460>Löschung (Art. 17 DSGVO):</strong> Recht auf Löschung Ihrer bei uns gespeicherten Daten.</li><li data-v-e5407460><strong data-v-e5407460>Einschränkung der Verarbeitung (Art. 18 DSGVO):</strong> Recht, die Einschränkung der Verarbeitung Ihrer Daten zu verlangen.</li><li data-v-e5407460><strong data-v-e5407460>Datenübertragbarkeit (Art. 20 DSGVO):</strong> Recht, Ihre Daten in einem strukturierten, gängigen und maschinenlesbaren Format zu erhalten.</li><li data-v-e5407460><strong data-v-e5407460>Widerruf Ihrer Einwilligung (Art. 7 Abs. 3 DSGVO):</strong> Sie können eine bereits erteilte Einwilligung jederzeit für die Zukunft widerrufen.</li></ul></article><article class="lise-ds-block" data-v-e5407460><h2 data-v-e5407460>5. Widerspruchsrecht gegen die Datenerhebung (Art. 21 DSGVO)</h2><p data-v-e5407460> WENN DIE DATENVERARBEITUNG AUF GRUNDLAGE VON ART. 6 ABS. 1 LIT. E ODER F DSGVO ERFOLGT, HABEN SIE JEDERZEIT DAS RECHT, AUS GRÜNDEN, DIE SICH AUS IHRER BESONDEREN SITUATION ERGEBEN, GEGEN DIE VERARBEITUNG IHRER PERSONENBEZOGENEN DATEN WIDERSPRUCH EINZULEGEN. </p></article></div></div></section></main>`,1),n(u,{companyName:`STN ENTERPRISES GmbH`})]))}}),[[`__scopeId`,`data-v-e5407460`]]);export{f as default};